package com.minova.cloud;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.concurrent.*;
public final class AppUpdateActivity extends Activity {
    final ExecutorService io=Executors.newSingleThreadExecutor();final Handler handler=new Handler(Looper.getMainLooper());TextView state;Button install;boolean autoInstall,checking,pendingPermission;
    final Runnable refresh=new Runnable(){public void run(){render();if(autoInstall&&!checking){AppUpdater.Release release=AppUpdater.available(AppUpdateActivity.this);if(release!=null&&AppUpdater.file(AppUpdateActivity.this,release).isFile()){autoInstall=false;update();}}handler.postDelayed(this,1000);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(MinovaUi.NIGHT);getWindow().setNavigationBarColor(MinovaUi.NIGHT);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(28,60,28,40);root.setBackgroundColor(MinovaUi.NIGHT);setContentView(root);TextView title=new TextView(this);title.setText("Minova Cloud updates");title.setTextColor(MinovaUi.WHITE);title.setTextSize(25);root.addView(title);TextView version=new TextView(this);version.setText("Installed version "+BuildConfig.VERSION_NAME+"\nUpdates are checked automatically. Downloads use Wi-Fi by default. Android asks you to approve installation.");version.setTextColor(MinovaUi.MUTED);version.setPadding(0,24,0,24);root.addView(version);state=new TextView(this);state.setTextColor(MinovaUi.CYAN);state.setPadding(0,20,0,20);root.addView(state);
        Button check=new Button(this);check.setText("Check for updates");check.setOnClickListener(v->check(false));root.addView(check);install=new Button(this);install.setOnClickListener(v->update());root.addView(install);Switch wifi=new Switch(this);wifi.setText("Automatically download on Wi-Fi only");wifi.setTextColor(MinovaUi.WHITE);wifi.setChecked(AppUpdater.settings(this).getBoolean("wifiOnly",true));wifi.setOnCheckedChangeListener((v,checked)->AppUpdater.settings(this).edit().putBoolean("wifiOnly",checked).apply());root.addView(wifi);Button notifications=new Button(this);notifications.setText("Enable update notifications");notifications.setOnClickListener(v->{if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},503);else startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));});root.addView(notifications);Button close=new Button(this);close.setText("Back");close.setOnClickListener(v->finish());root.addView(close);autoInstall=getIntent().getBooleanExtra("install",false);getIntent().removeExtra("install");AppUpdater.schedule(this);handler.post(refresh);check(autoInstall);
        root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());int padding=MinovaUi.dp(this,22);v.setPadding(bars.left+padding,bars.top+padding,bars.right+padding,bars.bottom+padding);}return insets;});
    }
    void check(boolean download){if(checking)return;checking=true;io.execute(()->{try{AppUpdater.check(this,download);}catch(Exception ignored){}runOnUiThread(()->{checking=false;render();AppUpdater.Release release=AppUpdater.available(this);if(autoInstall&&release!=null&&AppUpdater.file(this,release).isFile()){autoInstall=false;update();}});});}
    void render(){if(state==null||isFinishing())return;state.setText(AppUpdater.settings(this).getString("status","Checking for updates…"));AppUpdater.Release release=AppUpdater.available(this);install.setEnabled(release!=null);install.setText(release!=null&&AppUpdater.file(this,release).isFile()?"Install downloaded update":"Download update");}
    void update(){if(checking)return;AppUpdater.Release release=AppUpdater.available(this);if(release==null)return;if(!AppUpdater.file(this,release).isFile()){autoInstall=true;check(true);return;}io.execute(()->{try{AppUpdater.verifyArchive(this,AppUpdater.file(this,release),release,AppUpdater.installedCertificate(this));runOnUiThread(()->{try{pendingPermission=!getPackageManager().canRequestPackageInstalls();AppUpdater.install(this,release);}catch(Exception error){state.setText(error.getMessage());}});}catch(Exception error){runOnUiThread(()->state.setText(error.getMessage()));}});}
    @Override protected void onResume(){super.onResume();render();if(pendingPermission){pendingPermission=false;if(getPackageManager().canRequestPackageInstalls())update();}}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
}
